OPENOCD_SCRIPTS="/mnt/d/Develop/xpack-openocd-0.12.0-7/openocd/scripts"

setup_build_env() {
  export PATH="$OPENVELA_DIR/prebuilts/tools/python/bin:$OPENVELA_DIR/prebuilts/tools/linux/x86_64:$OPENVELA_DIR/prebuilts/kconfig-frontends/bin:$OPENVELA_DIR/prebuilts/gcc/linux-x86_64/arm-none-eabi/bin:$OPENVELA_DIR/prebuilts/build-tools/linux-x86_64/bin:$PATH"
  export PYTHONPATH="$OPENVELA_DIR/prebuilts/tools/python/dist-packages/kconfiglib:$OPENVELA_DIR/prebuilts/tools/python/dist-packages:${PYTHONPATH:-}"
}

ensure_contest_links() {
  local velaguard_link="$OPENVELA_DIR/packages/demos/contest2026_004_velaguard_app"

  if [[ -L "$velaguard_link" || ! -e "$velaguard_link" ]]; then
    mkdir -p "$OPENVELA_DIR/packages/demos"
    ln -sfn "$REPO_DIR/app/velaguard_app" "$velaguard_link"
  else
    echo "error: not replacing existing non-symlink: $velaguard_link" >&2
    exit 1
  fi

  (cd "$OPENVELA_DIR/packages/demos" && "$OPENVELA_DIR/apps/tools/mkkconfig.sh" -m Demos)
}

configure_velaguard() {
  echo "==> Configuring VelaGuard firmware"
  ensure_contest_links
  bash "$REPO_DIR/scripts/apply-openvela-issue1-patches.sh"
  "$NUTTX_DIR/tools/configure.sh" -e stm32h750b-dk:lvgl

  before_config="$(mktemp)"
  cp "$NUTTX_DIR/.config" "$before_config"
  kconfig-tweak --file "$NUTTX_DIR/.config" \
    --set-str CONFIG_INIT_ENTRYPOINT velaguard_main \
    --set-str CONFIG_INIT_ENTRYNAME velaguard \
    --enable CONFIG_LVX_USE_VELAGUARD \
    --enable CONFIG_STM32H750B_DK_QSPI_BOOT \
    --disable CONFIG_LVX_USE_DEMO_CONTEST2026_004_HELLO_APP \
    --disable CONFIG_LVX_USE_DEMO_CONTEST2026_000_HELLO_APP \
    --disable CONFIG_EXAMPLES_LVGLDEMO
  make -C "$NUTTX_DIR" olddefconfig

  if ! cmp -s "$before_config" "$NUTTX_DIR/.config"; then
    make -C "$NUTTX_DIR" clean
  fi
  rm -f "$before_config"
}

build_firmware() {
  if [[ ! -d "$NUTTX_DIR" ]]; then
    echo "error: NuttX directory not found: $NUTTX_DIR" >&2
    exit 1
  fi

  echo "==> Building openvela firmware"
  setup_build_env
  configure_velaguard
  make -C "$NUTTX_DIR" -j"$(nproc)"

  local bootstub_build_dir="$NUTTX_DIR/qspi_boot_stub"
  bash "$REPO_DIR/scripts/qspi_boot_stub/build_bootstub.sh" "$bootstub_build_dir"
  cp "$bootstub_build_dir/qspi_bootstub.hex" "$BOOTSTUB_HEX_PATH"
}

flash_firmware() {
  if [[ ! -f "$HEX_PATH" ]]; then
    echo "error: firmware not found after build: $HEX_PATH" >&2
    exit 1
  fi

  if [[ ! -f "$BOOTSTUB_HEX_PATH" ]]; then
    echo "error: QSPI boot stub not found after build: $BOOTSTUB_HEX_PATH" >&2
    exit 1
  fi

  python3 - "$HEX_PATH" <<'PY'
import sys
from pathlib import Path

path = Path(sys.argv[1])
base = 0
lo = None
hi = 0
for line in path.read_text(encoding="ascii").splitlines():
    if not line.startswith(":"):
        continue
    count = int(line[1:3], 16)
    offset = int(line[3:7], 16)
    rectype = int(line[7:9], 16)
    if rectype == 0:
        start = base + offset
        end = start + count
        lo = start if lo is None else min(lo, start)
        hi = max(hi, end)
    elif rectype == 4:
        base = int(line[9:13], 16) << 16

if lo is None or lo < 0x90000000 or hi > 0x98000000:
    print(
        f"error: main image must be linked to QSPI 0x90000000..0x97ffffff, got 0x{lo or 0:08x}..0x{hi:08x}",
        file=sys.stderr,
    )
    sys.exit(1)
PY

  if [[ ! -x "$OPENOCD_BIN" ]]; then
    echo "error: OpenOCD not found or not executable: $OPENOCD_BIN" >&2
    exit 1
  fi

  echo "==> Flashing QSPI boot stub and main image"
  cp "$BOOTSTUB_HEX_PATH" "$WIN_BOOTSTUB_HEX_PATH"
  cp "$HEX_PATH" "$WIN_HEX_PATH"

  SCRIPT_WIN="$(wslpath -w "$OPENOCD_SCRIPTS")"

  "$OPENOCD_BIN" \
    -s "$SCRIPT_WIN" \
    -f board/stm32h750b-disco.cfg \
    -c "init" \
    -c "reset init" \
    -c "program C:/Users/19y/AppData/Local/Temp/openvela_qspi_nuttx.hex verify" \
    -c "program C:/Users/19y/AppData/Local/Temp/openvela_qspi_bootstub.hex verify" \
    -c "reset run" \
    -c "shutdown"
}

